// Extract payload from Django PPC portal.
// Expected: { report_key, tab_name, headers, rows, row_count, _meta }
//
// The portal sends human-readable header-keyed rows — ready for the sheet.
// We just pass through tab_name + rows and add a timestamp header row.

const input = $input.first().json;
const tabName = input.tab_name;
const headers = input.headers || [];
const rows    = input.rows || [];
const meta    = input._meta || {};

if (!tabName) {
  throw new Error('Missing tab_name in payload — report_key: ' + (input.report_key || 'unknown'));
}
if (!rows.length) {
  throw new Error('No rows in payload for tab: ' + tabName);
}

// Pass metadata forward for the Sheet nodes
return [{
  json: {
    tab_name: tabName,
    report_key: input.report_key,
    headers: headers,
    rows: rows,
    row_count: rows.length,
    uploaded_by: meta.uploader || 'unknown',
    uploaded_at: meta.uploaded_at || new Date().toISOString(),
    original_file: meta.original_filename || '',
  }
}];

// Expand the rows array into individual n8n items for Sheets append.
// Each item becomes one row in the Google Sheet.

const data = $input.first().json;
const rows = data.rows || [];
const headers = data.headers || [];

// If the sheet was just cleared, the first item carries the header info.
// Google Sheets node in 'append' mode with headerRow=autoMapInputData
// will use the first item's keys as column headers.

return rows.map(row => {
  // Ensure consistent column order matching headers
  const ordered = {};
  for (const h of headers) {
    ordered[h] = row[h] !== undefined ? row[h] : '';
  }
  return { json: ordered };
});

// Log summary — optional, for the n8n execution log.
const data = $('Parse Payload').first().json;
const appended = $input.all().length;

return [{
  json: {
    status: 'done',
    tab: data.tab_name,
    report_key: data.report_key,
    rows_written: appended,
    uploaded_by: data.uploaded_by,
    uploaded_at: data.uploaded_at,
    original_file: data.original_file,
  }
}];
